    public static string Language { get; private set; } = "en";

    public static void SetLanguage(string language) =>
        Language = language is "de" or "en" or "ru" or "es" ? language : "en";

    public static string T(string key, params object[] arguments)
    {
        if (!Strings.TryGetValue(key, out string[]? values))
            return key;
        int index = Language switch { "de" => 0, "en" => 1, "ru" => 2, "es" => 3, _ => 1 };
        string value = values[index];
        return arguments.Length == 0 ? value : string.Format(CultureInfo.CurrentCulture, value, arguments);
    }

    public static string GovernorStatus(DccGovernorStatus status, double fps, int targetFps) => status switch
    {
        DccGovernorStatus.WaitingForGame => T("waiting_game"),
        DccGovernorStatus.Baseline => T("status_baseline"),
        DccGovernorStatus.InvalidFps => T("status_invalid_fps"),
        DccGovernorStatus.VerifyLearnedProfile => T("status_verify"),
        DccGovernorStatus.Learning => T("status_learning"),
        DccGovernorStatus.FineTuning => T("status_tuning"),
        DccGovernorStatus.ReducingClockHeadroom => T("status_reducing"),
        DccGovernorStatus.RecheckingEfficiency => T("status_rechecking"),
        DccGovernorStatus.LowerClockConfirmed => targetFps == DccLearnedProfile.AutomaticTargetFps
            ? T("status_lower_confirmed_auto", fps)
            : T("status_lower_confirmed", fps, targetFps),
        DccGovernorStatus.StableClockRestored => T("status_clock_restored"),
        DccGovernorStatus.IncreasingFpsHeadroom => T("status_increasing"),
        DccGovernorStatus.Rebaseline => T("status_rebaseline"),
        DccGovernorStatus.CpuOrGameLimited => targetFps == DccLearnedProfile.AutomaticTargetFps
            ? T("status_cpu_limit_auto", fps)
            : T("status_cpu_limit", fps, targetFps),
        DccGovernorStatus.TargetUnreachableWithoutDcc => T("status_unreachable", fps, targetFps),
        DccGovernorStatus.WaitingForReachableTarget => T("status_wait_target"),
        DccGovernorStatus.TargetUnstable => T("status_target_unstable"),
        DccGovernorStatus.ProfileLearned => targetFps == DccLearnedProfile.AutomaticTargetFps
            ? T("status_profile_learned_auto", fps)
            : T("status_profile_learned", fps, targetFps),
        DccGovernorStatus.ProfileAdjusted => targetFps == DccLearnedProfile.AutomaticTargetFps
            ? T("status_profile_adjusted_auto", fps)
            : T("status_profile_adjusted", fps, targetFps),
        DccGovernorStatus.Regulated => fps > 0
            ? targetFps == DccLearnedProfile.AutomaticTargetFps
                ? T("status_regulated_auto", fps)
                : T("status_regulated", fps, targetFps)
            : T("status_learning"),
        DccGovernorStatus.LoadingOrCpuLimited => T("status_loading_cpu"),
        _ => T("status_learning")
    };
}
